// Fast lookup map by assessmentId
export const assessmentMap = allAssessmentList.reduce((acc, item) => {
  acc[item.id] = item;
  return acc;
}, {});

// Lookup subjects by code
export const subjectAssessmentMap = officialAssessmentSubjects.reduce((acc, item) => {
  acc[item.code] = item;
  if (item.id) acc[item.id] = item;
  acc[item.name.toLowerCase()] = item;
  return acc;
}, {});

/**
 * Returns subject assessment data by subjectCode, subjectId, or subjectName
 */
export function getSubjectAssessments(identifier) {
  if (!identifier) return null;
  const key = String(identifier).trim().toLowerCase();
  return (
    subjectAssessmentMap[identifier] ||
    subjectAssessmentMap[key] ||
    officialAssessmentSubjects.find(
      (s) => s.code.toLowerCase() === key || s.name.toLowerCase() === key || s.id === key
    ) ||
    null
  );
}

/**
 * Returns a specific assessment (Unit Quiz or Unit Completion Assessment)
 */
export function getAssessmentById(assessmentId) {
  return assessmentMap[assessmentId] || null;
}
